 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trmm.h"

/* Include the Exo-generated kernel header. */
#include "generated/trmm/trmm.h"


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  for (i = 0; i < m; i++) {
    for (j = 0; j < i; j++) {
      A[i][j] = (DATA_TYPE)((i+j) % m)/m;
    }
    A[i][i] = 1.0;
    for (j = 0; j < n; j++) {
      B[i][j] = (DATA_TYPE)((n+(i-j)) % n)/n;
    }
 }

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("B");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline TRMM kernel:
# B := alpha * A^T * B, where A is unit-lower-triangular.
# A is stored as a full matrix; the strictly upper part is ignored.
@proc
def kernel_trmm_base(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    # First compute the triangular matrix-matrix product:
    #   B[i, j] += sum_{k=i+1}^{m-1} A[k, i] * B[k, j]
    # This uses B in-place but always reads rows k > i, which have not
    # yet been updated, matching the standard TRMM algorithm.
    for i in seq(0, m):
        for j in seq(0, n):
            for k in seq(i + 1, m):
                B[i, j] += A[k, i] * B[k, j]

    # Then scale the whole result by alpha:
    #   B[i, j] = alpha * B[i, j]
    # Moving this scaling out of the innermost loop is safe because
    # alpha is a scalar and multiplication distributes over addition.
    for i in seq(0, m):
        for j in seq(0, n):
            B[i, j] = alpha * B[i, j]


# ------------------------------------------------------------------
# Optimization schedule
# ------------------------------------------------------------------
# We apply a cache- and parallelism-friendly schedule:
#   - Reorder loops to access B contiguously in memory.
#   - Tile the column (j) dimension to improve locality.
#   - Parallelize over column tiles; tiles are independent because
#     each column of B is updated using only that column.
# ------------------------------------------------------------------

# Column tile size (number of columns per tile). This can be tuned
# for the target cache hierarchy.
Tj = 64

p = kernel_trmm_base

# ---- Triangular update phase -------------------------------------
# Original (update part only):
#   for i in 0..m:
#     for j in 0..n:
#       for k in i+1..m:
#         ...
#
# 1) Reorder inner loops so that 'k' is outside and 'j' is innermost.
#    This keeps accesses to B[k, j] and B[i, j] contiguous in j.
p = reorder_loops(p, "j k")   # -> for i, for k, for j

# 2) Tile the j loop to operate on column blocks of size Tj.
#    This produces loops:
#      for i:
#        for k:
#          for jo:  # tile index
#            for ji:  # intra-tile column
#                j = jo*Tj + ji
p = divide_loop(p, "j", Tj, ("jo", "ji"), tail="guard")

# 3) Move the tile loop 'jo' to the outermost position so that we can
#    parallelize over column tiles. Each tile touches a disjoint set
#    of columns of B and is therefore independent.
p = reorder_loops(p, "k jo")  # -> for i, for jo, for k, for ji
p = reorder_loops(p, "i jo")  # -> for jo, for i, for k, for ji

# At this point, the update phase has structure:
#   for jo in tiles:
#     for i in rows:
#       for k in i+1..m:
#         for ji in 0..Tj:
#           if jo*Tj + ji < n:
#               B[i, jo*Tj+ji] += A[k, i] * B[k, jo*Tj+ji]
# Accesses to B along ji are contiguous, and different jo-iterations
# touch disjoint column ranges.

# ---- Scaling phase -----------------------------------------------
# Original scaling:
#   for i in 0..m:
#     for j in 0..n:
#       B[i, j] = alpha * B[i, j]
#
# Apply the same column tiling pattern so that both phases traverse B
# in a similar, cache-friendly order.

p = divide_loop(p, "j", Tj, ("jo_s", "ji_s"), tail="guard")  # scale: for i, for jo_s, for ji_s
p = reorder_loops(p, "i jo_s")  # -> for jo_s, for i, for ji_s

# ---- Parallelization ---------------------------------------------
# Parallelize over column tiles in both phases. Each tile operates on
# a distinct slice of B, so there are no cross-iteration dependencies.
p = parallelize_loop(p, "jo")
p = parallelize_loop(p, "jo_s")

# Expose the scheduled kernel under the name used by the C driver.
kernel_trmm = p
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_trmm (/*ctxt=*/NULL, m, n,
               (DATA_TYPE*)&alpha,
               (DATA_TYPE*)POLYBENCH_ARRAY(A),
               (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
