from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Triangular matrix-matrix multiply kernel.
# Semantics:
#   B[i, j] <- alpha * ( B[i, j] + sum_{k=i+1..m-1} A[k, i] * B[k, j] )
# A is a unit-diagonal lower-triangular matrix stored in row-major DRAM.
# B is an m x n matrix stored in row-major DRAM.
@proc
def kernel_trmm(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
