        # B[k, j] is read-only here and equal to its initial value B0[k, j]
        # because row k is only scaled when i == k, after all i < k have
        # consumed B[k, j].
        for k in seq(i + 1, m):
            a_ki: DATA_TYPE
            a_ki = A[k, i]
            for j in seq(0, n):
                B[i, j] += a_ki * B[k, j]

        # Once all contributions from k > i have been accumulated into row i,
        # scale that row by alpha. This matches the original PolyBench/TRMM
        # semantics: B[i, j] = alpha * (B0[i, j] + sum_k A[k, i] * B0[k, j]).
