#       for j in seq(0, n):
#           B[i, j] += a_ki * B[k, j]
#    becomes something like:
#       for jo in seq(0, n / J_TILE):
#           for ji in seq(0, J_TILE):
#               guarded body using j = J_TILE*jo + ji
