#       for j in seq(0, n):
#           B[i, j] = alpha * B[i, j]
#    We tile and unroll it analogously.
kernel_trmm = divide_loop(kernel_trmm, "j #0", J_TILE, ["jo_s", "ji_s"], tail="guard")
kernel_trmm = unroll_loop(kernel_trmm, "ji_s")
