# original PolyBench kernel:
#
#   Original:
#     for i in 0..m-1
#       for j in 0..n-1
#         for k in i+1..m-1
#           B[i,j] += A[k,i] * B[k,j]
#         B[i,j] = alpha * B[i,j]
#
#   Here we first compute the triangular matrix-matrix product
#     B[i,j] += sum_{k>i} A[k,i] * B[k,j]
#   and then scale the entire result by alpha.
#
# Because each term in the sum only depends on the *original* contents of
# the rows B[k,*], and those rows are not modified until after all their
# contributions have been used, this reordering is mathematically
# equivalent to the original TRMM computation.
# ---------------------------------------------------------------------------
@proc
def kernel_trmm_base(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
