    #
    #   B[i, j] += sum_{k = i+1}^{m-1} A[k, i] * B[k, j]
    #
    # Loops are ordered as (i, k, j) so that the innermost loop runs over
    # contiguous columns j. This improves spatial locality and makes the
    # kernel easier for the C compiler to vectorize.
    for i in seq(0, m):
        for k in seq(i + 1, m):
            # Hoist A[k, i] out of the innermost j loop to avoid repeatedly
            # loading the same scalar inside the vectorized loop.
            a_ki: DATA_TYPE
            a_ki = A[k, i]
            for j in seq(0, n):
                B[i, j] += a_ki * B[k, j]

