    #
    #   B[i, j] = alpha * B[i, j]
    #
    # This phase is completely pointwise and has no cross-iteration
    # dependencies, which makes it a good candidate for parallelization.
    for i in seq(0, m):
        for j in seq(0, n):
            B[i, j] = alpha * B[i, j]


# ---------------------------------------------------------------------------
# Scheduling
# ---------------------------------------------------------------------------

trmm_opt = kernel_trmm_base

# 1) Parallelize the scaling phase.
#
# There are two loops named "i" in kernel_trmm_base:
#   - the outer i-loop of the triangular multiply (phase 1)
#   - the outer i-loop of the scaling phase (phase 2)
#
# We parallelize only the *second* one, because different rows in the
# scaling phase are independent, while the first phase has loop-carried
# dependencies through B[k, j].
scale_i = trmm_opt.find_loop("i #1")
