#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trmm.h"

/* Include the Exo-generated kernel header. */
#include "generated/trmm/trmm.h"


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  for (i = 0; i < m; i++) {
    for (j = 0; j < i; j++) {
      A[i][j] = (DATA_TYPE)((i+j) % m)/m;
    }
    A[i][i] = 1.0;
    for (j = 0; j < n; j++) {
      B[i][j] = (DATA_TYPE)((n+(i-j)) % n)/n;
    }
 }

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("B");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base TRMM kernel: same semantics as the original PolyBench kernel.
# Computes, for a lower-triangular A:
#   for i in 0..m-1:
#     for j in 0..n-1:
#       B[i,j] = alpha * ( B[i,j] + sum_{k=i+1..m-1} A[k,i] * B[k,j] )
@proc
def trmm_base(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    for i in seq(0, m):
        for j in seq(0, n):
            for k in seq(i + 1, m):
                B[i, j] += A[k, i] * B[k, j]
            B[i, j] = alpha * B[i, j]

# ---------------------------------------------------------------------------
# Scheduling / optimization
# ---------------------------------------------------------------------------
# 1. Reorder the inner (j,k) loops to (k,j) for better spatial locality on B.
#    After this transformation, for each (i,k) pair we sweep j contiguously,
#    accessing B[i, j] and B[k, j] in row-major order.
trmm_scheduled = reorder_loops(trmm_base, "j k")

# 2. Parallelize the innermost j loop. For fixed (i,k), all columns j are
#    independent: each iteration updates B[i, j] using only B[k, j], so there
#    are no cross-j dependencies. This lowers to an OpenMP parallel-for
#    pragma in the generated C, but compiles fine even without -fopenmp.
j_loop = trmm_scheduled.find_loop("j")
trmm_scheduled = parallelize_loop(trmm_scheduled, j_loop)

# 3. Expose the optimized kernel to C as 'kernel_trmm'.
kernel_trmm = rename(trmm_scheduled, "kernel_trmm")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_trmm (/*ctxt=*/NULL, m, n,
               (DATA_TYPE*)&alpha,
               (DATA_TYPE*)POLYBENCH_ARRAY(A),
               (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
